<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Activity, Check, CircleAlert, Database, FilePlus2, Globe2, Import, ListPlus, SearchCheck, RefreshCw, RotateCw, Trash2, X } from 'lucide-vue-next'
import { ElMessage } from 'element-plus/es/components/message/index'
import { normalizeApiError } from '@/services/api'
import { createKnowledgeSource, createPoiImportJob, createStructuredKnowledgeImportJob, createWebSearchJob, decideCommunityKnowledgeReview, decideExternalWebKnowledgeSource, decideKnowledgeSource, decideWebSearchCandidate, getAiMetrics, getAiWorkflowHealth, listCommunityKnowledgeReviews, listExternalWebKnowledgeSources, listGenerationAudit, listKnowledgeSources, listPoiImportJobs, listStructuredKnowledgeImportJobs, listWebSearchCandidates, listWebSearchJobs, previewRetrieval, retryPoiImportJob, retryStructuredKnowledgeImportJob, type AiMetrics, type AiWorkflowHealth, type CommunityKnowledgeReview, type ExternalWebKnowledgeSource, type GenerationAuditItem, type KnowledgeSource, type PoiImportJob, type RetrievalPreview, type StructuredKnowledgeImportEntry, type StructuredKnowledgeImportJob, type WebSearchCandidate, type WebSearchJob } from '../services/aiOperations'

const tab = ref<'knowledge' | 'jobs'>('knowledge')
const status = ref('')
const sources = ref<KnowledgeSource[]>([])
const jobs = ref<GenerationAuditItem[]>([])
const importJobs = ref<PoiImportJob[]>([])
const structuredImportJobs = ref<StructuredKnowledgeImportJob[]>([])
const metrics = ref<AiMetrics | null>(null)
const workflowHealth = ref<AiWorkflowHealth | null>(null)
const workflowHealthLoading = ref(false)
const workflowHealthError = ref('')
const loading = ref(false)
const error = ref('')
const createOpen = ref(false)
const importOpen = ref(false)
const structuredImportOpen = ref(false)
const retrievalOpen = ref(false)
const form = ref({ source_type: 'rule' as KnowledgeSource['source_type'], title: '', body_text: '', city_code: '', poi_id: '', language: 'zh-CN' })
const importForm = ref({ city_code: '330100', keywords: '' })
const structuredImportForm = ref({ city_code: '330100', entries: [{ source_type: 'rule' as StructuredKnowledgeImportEntry['source_type'], title: '', body_text: '' }] })
const retrievalForm = ref({ city_code: '330100', query: '' })
const retrievalResult = ref<RetrievalPreview | null>(null)
const retrievalLoading = ref(false)
const retrievalError = ref('')
const webSearchJobs = ref<WebSearchJob[]>([])
const webSearchCandidates = ref<WebSearchCandidate[]>([])
const externalWebSources = ref<ExternalWebKnowledgeSource[]>([])
const communityKnowledgeReviews = ref<CommunityKnowledgeReview[]>([])
const webSearchJobId = ref('')
const webSearchLoading = ref(false)
const webSearchError = ref('')
const webSearchOpen = ref(false)
const approveCandidateOpen = ref(false)
const rejectCandidateOpen = ref(false)
const rejectExternalSourceOpen = ref(false)
const selectedCandidate = ref<WebSearchCandidate | null>(null)
const selectedExternalSource = ref<ExternalWebKnowledgeSource | null>(null)
const selectedCommunityKnowledgeReview = ref<CommunityKnowledgeReview | null>(null)
const webSearchForm = ref({ city_code: '330100', query: '', target_domain: 'official' as WebSearchJob['target_domain'] })
const candidateForm = ref({ title: '', body_text: '', reason: '' })
const externalSourceReason = ref('')
const communityReviewOpen = ref(false)
const communityReviewDecision = ref<'approved' | 'rejected'>('approved')
const communityReviewReason = ref('')
const pending = computed(() => sources.value.filter((item) => item.status === 'pending_review').length)
const indexed = computed(() => sources.value.filter((item) => item.status === 'indexed').length)
const failed = computed(() => sources.value.filter((item) => item.status === 'failed').length)

function statusLabel(value: string) { return ({ draft: '草稿', pending: '待审核', pending_review: '待审核', needs_human_review: '待人工审核', approved: '已通过', indexing: '索引中', indexed: '已索引', removing: '移除中', failed: '失败', rejected: '已拒绝', inactive: '已停用', queued: '排队', running: '搜索中', understanding: '理解需求', retrieving: '检索', planning: '规划', validating: '校验', awaiting_confirmation: '待确认', succeeded: '完成', cancelled: '取消' } as Record<string, string>)[value] ?? value }
function tagType(value: string) { return value === 'failed' || value === 'rejected' ? 'danger' : value === 'pending_review' || value === 'indexing' || value === 'removing' || value === 'queued' ? 'warning' : 'success' }
async function load() { loading.value = true; error.value = ''; try { const metricsRequest = getAiMetrics(); if (tab.value === 'knowledge') [sources.value, importJobs.value, structuredImportJobs.value, metrics.value] = await Promise.all([listKnowledgeSources(status.value || undefined), listPoiImportJobs(), listStructuredKnowledgeImportJobs(), metricsRequest]); else [jobs.value, metrics.value] = await Promise.all([listGenerationAudit(status.value || undefined), metricsRequest]) } catch (cause) { error.value = normalizeApiError(cause).message } finally { loading.value = false } }
async function refreshWorkflowHealth() { workflowHealthLoading.value = true; workflowHealthError.value = ''; try { workflowHealth.value = await getAiWorkflowHealth() } catch (cause) { workflowHealth.value = null; workflowHealthError.value = normalizeApiError(cause).message } finally { workflowHealthLoading.value = false } }
async function submit() { if (!form.value.title.trim() || !form.value.body_text.trim() || !form.value.city_code.trim()) return; try { await createKnowledgeSource({ ...form.value, title: form.value.title.trim(), body_text: form.value.body_text.trim(), city_code: form.value.city_code.trim(), poi_id: form.value.poi_id.trim() || null }); createOpen.value = false; form.value = { source_type: 'rule', title: '', body_text: '', city_code: '', poi_id: '', language: 'zh-CN' }; ElMessage.success('资料已提交到待审核队列。'); await load() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
async function decide(item: KnowledgeSource, next: 'indexed' | 'rejected') { const reason = next === 'indexed' ? '内容与城市范围已复核，可进入公开知识库。' : '资料不符合公开知识库要求。'; try { await decideKnowledgeSource(item.id, next, reason); ElMessage.success(next === 'indexed' ? '已提交索引任务。' : '资料已拒绝。'); await load() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
async function remove(item: KnowledgeSource) { try { await decideKnowledgeSource(item.id, 'inactive', 'Retire this public knowledge source and remove its retrieval projections.'); ElMessage.success('已提交双索引移除任务。'); await load() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
async function submitImport() { const keywords = importForm.value.keywords.split(/[\n,]/).map((item) => item.trim()).filter(Boolean); if (!importForm.value.city_code.trim() || !keywords.length) return; try { await createPoiImportJob(importForm.value.city_code.trim(), keywords); importOpen.value = false; importForm.value.keywords = ''; ElMessage.success('高德 POI 导入任务已进入队列。'); await load() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
async function retryImport(job: PoiImportJob) { try { await retryPoiImportJob(job.id); ElMessage.success('POI 导入任务已重试。'); await load() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
function addStructuredEntry() { structuredImportForm.value.entries.push({ source_type: 'rule', title: '', body_text: '' }) }
function removeStructuredEntry(index: number) { if (structuredImportForm.value.entries.length > 1) structuredImportForm.value.entries.splice(index, 1) }
async function submitStructuredImport() { const entries = structuredImportForm.value.entries.map((entry) => ({ ...entry, title: entry.title.trim(), body_text: entry.body_text.trim() })).filter((entry) => entry.title && entry.body_text); if (!structuredImportForm.value.city_code.trim() || !entries.length) return; try { await createStructuredKnowledgeImportJob(structuredImportForm.value.city_code.trim(), entries); structuredImportOpen.value = false; structuredImportForm.value.entries = [{ source_type: 'rule', title: '', body_text: '' }]; ElMessage.success('规则与模板导入任务已进入队列。'); await load() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
async function retryStructuredImport(job: StructuredKnowledgeImportJob) { try { await retryStructuredKnowledgeImportJob(job.id); ElMessage.success('规则与模板导入任务已重试。'); await load() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
async function submitRetrievalPreview() { if (!retrievalForm.value.city_code.trim() || !retrievalForm.value.query.trim()) return; retrievalLoading.value = true; retrievalError.value = ''; retrievalResult.value = null; try { retrievalResult.value = await previewRetrieval(retrievalForm.value.city_code.trim(), retrievalForm.value.query.trim()) } catch (cause) { retrievalError.value = normalizeApiError(cause).message } finally { retrievalLoading.value = false } }
async function loadWebSearchJobs() { webSearchLoading.value = true; webSearchError.value = ''; try { const [jobs, sources] = await Promise.all([listWebSearchJobs(), listExternalWebKnowledgeSources('pending_review')]); webSearchJobs.value = jobs; externalWebSources.value = sources; if (!webSearchJobs.value.some((job) => job.id === webSearchJobId.value)) webSearchJobId.value = webSearchJobs.value[0]?.id ?? ''; await loadWebSearchCandidates() } catch (cause) { webSearchError.value = normalizeApiError(cause).message } finally { webSearchLoading.value = false } }
async function loadWebSearchCandidates() { if (!webSearchJobId.value) { webSearchCandidates.value = []; return } try { webSearchCandidates.value = await listWebSearchCandidates(webSearchJobId.value) } catch (cause) { webSearchCandidates.value = []; webSearchError.value = normalizeApiError(cause).message } }
async function submitWebSearch() { if (!webSearchForm.value.city_code.trim() || !webSearchForm.value.query.trim()) return; try { const job = await createWebSearchJob({ ...webSearchForm.value, city_code: webSearchForm.value.city_code.trim(), query: webSearchForm.value.query.trim() }); webSearchOpen.value = false; webSearchForm.value.query = ''; webSearchJobId.value = job.id; ElMessage.success('网页搜索任务已进入队列。'); await loadWebSearchJobs() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
function openCandidateApproval(candidate: WebSearchCandidate) { selectedCandidate.value = candidate; candidateForm.value = { title: candidate.title, body_text: candidate.excerpt, reason: '' }; approveCandidateOpen.value = true }
function openCandidateRejection(candidate: WebSearchCandidate) { selectedCandidate.value = candidate; candidateForm.value = { title: '', body_text: '', reason: '' }; rejectCandidateOpen.value = true }
async function approveCandidate() { const candidate = selectedCandidate.value; if (!candidate || !candidateForm.value.title.trim() || !candidateForm.value.body_text.trim()) return; try { await decideWebSearchCandidate(candidate.id, { status: 'approved', title: candidateForm.value.title.trim(), body_text: candidateForm.value.body_text.trim() }); approveCandidateOpen.value = false; ElMessage.success('候选资料已进入既有知识审核流程。'); await loadWebSearchJobs() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
async function rejectCandidate() { const candidate = selectedCandidate.value; if (!candidate || !candidateForm.value.reason.trim()) return; try { await decideWebSearchCandidate(candidate.id, { status: 'rejected', reason: candidateForm.value.reason.trim() }); rejectCandidateOpen.value = false; ElMessage.success('候选资料已拒绝。'); await loadWebSearchJobs() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
async function approveExternalSource(source: ExternalWebKnowledgeSource) { try { await decideExternalWebKnowledgeSource(source.id, { status: 'approved' }); ElMessage.success('二次审核已通过，资料已提交索引。'); await loadWebSearchJobs() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
function openExternalSourceRejection(source: ExternalWebKnowledgeSource) { selectedExternalSource.value = source; externalSourceReason.value = ''; rejectExternalSourceOpen.value = true }
async function rejectExternalSource() { const source = selectedExternalSource.value; if (!source || !externalSourceReason.value.trim()) return; try { await decideExternalWebKnowledgeSource(source.id, { status: 'rejected', reason: externalSourceReason.value.trim() }); rejectExternalSourceOpen.value = false; ElMessage.success('二次审核已拒绝该资料。'); await loadWebSearchJobs() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
async function loadCommunityKnowledgeReviews() { try { communityKnowledgeReviews.value = await listCommunityKnowledgeReviews() } catch (cause) { ElMessage.error(normalizeApiError(cause).message); communityKnowledgeReviews.value = [] } }
function openCommunityKnowledgeReview(review: CommunityKnowledgeReview, decision: 'approved' | 'rejected') { selectedCommunityKnowledgeReview.value = review; communityReviewDecision.value = decision; communityReviewReason.value = ''; communityReviewOpen.value = true }
async function submitCommunityKnowledgeReview() { const review = selectedCommunityKnowledgeReview.value; if (!review || !communityReviewReason.value.trim()) return; try { await decideCommunityKnowledgeReview(review.post_id, { status: communityReviewDecision.value, reason: communityReviewReason.value.trim() }); communityReviewOpen.value = false; ElMessage.success(communityReviewDecision.value === 'approved' ? '社区帖子已通过，已提交社区 RAG 索引。' : '社区帖子已拒绝。'); await loadCommunityKnowledgeReviews() } catch (cause) { ElMessage.error(normalizeApiError(cause).message) } }
onMounted(() => { load(); refreshWorkflowHealth(); loadWebSearchJobs(); loadCommunityKnowledgeReviews() })
</script>

<template>
  <main class="ai-operations-page">
    <section class="page-heading"><div><h1>AI 知识运营</h1><p>审核公开资料、观察索引投影和去标识化生成状态。私人行程、对话和用户记忆不在此处展示。</p></div><div class="header-actions"><button class="icon-action" type="button" title="刷新" :disabled="loading" @click="load"><RefreshCw :size="18" :class="{ spinning: loading }" /></button><button class="secondary-button" type="button" @click="retrievalOpen = true"><SearchCheck :size="17" />检索验证</button><button class="secondary-button" type="button" @click="importOpen = true"><Import :size="17" />批量导入 POI</button><button class="secondary-button" type="button" @click="structuredImportOpen = true"><ListPlus :size="17" />批量导入规则模板</button><button class="primary-button" type="button" @click="createOpen = true"><FilePlus2 :size="17" />新增官方资料</button></div></section>
    <section class="summary" aria-label="AI 运营概览"><div><span>待审核</span><strong>{{ metrics?.knowledge.pending_review ?? pending }}</strong></div><div><span>已索引</span><strong>{{ metrics?.knowledge.indexed ?? indexed }}</strong></div><div><span>索引失败</span><strong>{{ metrics?.knowledge.failed ?? failed }}</strong></div><p><Database :size="17" />生成失败 {{ metrics?.generation.failed ?? 0 }} · 待用户确认 {{ metrics?.generation.awaiting_confirmation ?? 0 }} · POI 导入失败 {{ metrics?.imports.poi_failed ?? 0 }} · 规则模板导入失败 {{ metrics?.imports.structured_failed ?? 0 }}</p></section>
    <section class="workflow-health" aria-label="AI 工作流运行健康"><div class="health-heading"><div><Activity :size="18" /><div><strong>工作流运行健康</strong><span>仅显示当前队列状态与最近更新时间</span></div></div><button class="icon-action" type="button" title="刷新工作流运行健康" :disabled="workflowHealthLoading" @click="refreshWorkflowHealth"><RefreshCw :size="17" :class="{ spinning: workflowHealthLoading }" /></button></div><div v-if="workflowHealth" class="health-groups"><div><strong>Worker</strong><span>状态 {{ workflowHealth.worker.status === 'healthy' ? '正常' : workflowHealth.worker.status === 'stale' ? '心跳超时' : '不可用' }}</span><small>最近心跳 {{ workflowHealth.worker.last_heartbeat_at || '暂无' }}</small></div><div><strong>生成任务</strong><span>排队 {{ workflowHealth.generation_jobs.queued }} · 运行 {{ workflowHealth.generation_jobs.running }} · 失败 {{ workflowHealth.generation_jobs.failed }}</span><small>最近更新 {{ workflowHealth.generation_jobs.most_recent_at || '暂无' }}</small></div><div><strong>导出任务</strong><span>排队 {{ workflowHealth.export_tasks.queued }} · 运行 {{ workflowHealth.export_tasks.running }} · 失败 {{ workflowHealth.export_tasks.failed }}</span><small>最近更新 {{ workflowHealth.export_tasks.most_recent_at || '暂无' }}</small></div><div><strong>事件发件箱</strong><span>未处理 {{ workflowHealth.outbox.unprocessed }} · 重试中 {{ workflowHealth.outbox.retrying }} · 死信 {{ workflowHealth.outbox.dead_letter }}</span><small>最近更新 {{ workflowHealth.outbox.most_recent_at || '暂无' }}</small></div></div><div v-else-if="workflowHealthError" class="health-unavailable"><CircleAlert :size="18" /><span>运行健康暂不可用：{{ workflowHealthError }}</span><button type="button" @click="refreshWorkflowHealth">重新尝试</button></div><div v-else class="health-pending"><span>尚未获取运行健康。</span><button type="button" @click="refreshWorkflowHealth">立即刷新</button></div></section>
    <section class="workbench"><div class="toolbar"><div class="tabs" role="tablist"><button :class="{ active: tab === 'knowledge' }" type="button" role="tab" :aria-selected="tab === 'knowledge'" @click="tab = 'knowledge'; status = ''; load()">知识资料</button><button :class="{ active: tab === 'jobs' }" type="button" role="tab" :aria-selected="tab === 'jobs'" @click="tab = 'jobs'; status = ''; load()">生成任务</button></div><el-select v-model="status" placeholder="筛选状态" aria-label="状态筛选" @change="load"><el-option value="" label="全部状态" /><el-option v-if="tab === 'knowledge'" value="pending_review" label="待审核" /><el-option v-if="tab === 'knowledge'" value="indexing" label="索引中" /><el-option v-if="tab === 'knowledge'" value="indexed" label="已索引" /><el-option v-if="tab === 'knowledge'" value="failed" label="索引失败" /><el-option v-if="tab === 'jobs'" value="failed" label="失败" /><el-option v-if="tab === 'jobs'" value="awaiting_confirmation" label="待用户确认" /></el-select></div>
      <div v-if="error" class="error-state"><CircleAlert :size="20" /><div><strong>无法加载运营数据</strong><p>{{ error }}</p></div><button type="button" @click="load">重新尝试</button></div>
      <el-table v-else-if="tab === 'knowledge'" :data="sources" v-loading="loading" row-key="id"><el-table-column label="资料" min-width="260"><template #default="{ row }"><strong>{{ row.title }}</strong><small>{{ row.city_code }} · {{ row.source_type }}</small></template></el-table-column><el-table-column label="内容摘要" min-width="250"><template #default="{ row }"><span class="excerpt">{{ row.body_text }}</span></template></el-table-column><el-table-column label="状态" width="120"><template #default="{ row }"><el-tag effect="plain" :type="tagType(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="索引信息" min-width="190"><template #default="{ row }"><span v-if="row.index_error || row.removal_error" class="failure">{{ row.index_error || row.removal_error }}</span><span v-else>{{ row.indexed_at ? `已写入 ${row.indexed_at}` : '等待审核或任务处理' }}</span></template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{ row }"><button v-if="row.status === 'pending_review'" class="text-action" type="button" @click="decide(row, 'indexed')"><Database :size="16" />审核并索引</button><button v-if="row.status === 'pending_review'" class="text-action danger" type="button" @click="decide(row, 'rejected')">拒绝</button><button v-if="row.status === 'failed'" class="text-action" type="button" @click="decide(row, 'indexed')"><RotateCw :size="16" />重试索引</button><button v-if="row.status === 'indexed'" class="text-action danger" type="button" @click="remove(row)"><Trash2 :size="16" />移除索引</button></template></el-table-column></el-table>
      <el-table v-else :data="jobs" v-loading="loading" row-key="id"><el-table-column label="任务" min-width="260"><template #default="{ row }"><strong>{{ row.id }}</strong><small>{{ row.city_code }} · {{ row.created_at }}</small></template></el-table-column><el-table-column label="进度" width="100"><template #default="{ row }">{{ row.progress }}%</template></el-table-column><el-table-column label="状态" width="150"><template #default="{ row }"><el-tag effect="plain" :type="tagType(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="结果" min-width="260"><template #default="{ row }"><span :class="{ failure: row.error_code }">{{ row.error_code || row.message || row.outcome || '等待处理' }}</span></template></el-table-column></el-table>
      <div v-if="!loading && ((tab === 'knowledge' && !sources.length) || (tab === 'jobs' && !jobs.length))" class="empty-state">当前筛选条件下没有记录。</div><div v-if="tab === 'knowledge' && (importJobs.length || structuredImportJobs.length)" class="import-log"><strong>导入任务</strong><span v-for="job in importJobs" :key="job.id">POI · {{ job.city_code }} · {{ job.status }} · 新增 {{ job.imported_count }} / 跳过 {{ job.skipped_count }}<em v-if="job.error_message">{{ job.error_message }}</em><button v-if="job.status === 'failed'" type="button" @click="retryImport(job)">重试</button></span><span v-for="job in structuredImportJobs" :key="job.id">规则模板 · {{ job.city_code }} · {{ job.status }} · 新增 {{ job.imported_count }} / 跳过 {{ job.skipped_count }}<em v-if="job.error_message">{{ job.error_message }}</em><button v-if="job.status === 'failed'" type="button" @click="retryStructuredImport(job)">重试</button></span></div>
    </section>
    <el-dialog v-model="createOpen" width="min(620px, calc(100% - 32px))" title="新增官方知识资料" destroy-on-close><form class="source-form" @submit.prevent="submit"><el-select v-model="form.source_type" aria-label="资料类型"><el-option value="rule" label="旅行规则" /><el-option value="template" label="城市模板" /><el-option value="poi" label="验证 POI 说明" /></el-select><el-input v-model="form.title" maxlength="160" placeholder="资料标题" /><el-input v-model="form.city_code" maxlength="32" placeholder="城市行政区划代码，例如 330100" /><el-input v-if="form.source_type === 'poi'" v-model="form.poi_id" maxlength="128" placeholder="高德 POI ID" /><el-input v-model="form.body_text" type="textarea" :rows="8" maxlength="20000" show-word-limit placeholder="填写经复核、可公开引用的内容。不要包含用户行程、对话、联系方式或其他私人数据。" /><div class="dialog-actions"><button class="secondary-button" type="button" @click="createOpen = false">取消</button><button class="primary-button" type="submit">提交审核</button></div></form></el-dialog><el-dialog v-model="importOpen" width="min(540px, calc(100% - 32px))" title="批量导入高德验证 POI" destroy-on-close><form class="source-form" @submit.prevent="submitImport"><el-input v-model="importForm.city_code" maxlength="32" placeholder="城市行政区划代码，例如 330100" /><el-input v-model="importForm.keywords" type="textarea" :rows="6" maxlength="2000" placeholder="每行一个 POI 检索词，例如：西湖&#10;灵隐寺&#10;浙江省博物馆" /><p class="import-copy">系统对每个检索词选择一个同城高德 POI，保留导入审计，并让每条资料单独进入双索引。</p><div class="dialog-actions"><button class="secondary-button" type="button" @click="importOpen = false">取消</button><button class="primary-button" type="submit">提交导入</button></div></form></el-dialog><el-dialog v-model="structuredImportOpen" width="min(720px, calc(100% - 32px))" title="批量导入城市规则与模板" destroy-on-close><form class="source-form" @submit.prevent="submitStructuredImport"><el-input v-model="structuredImportForm.city_code" maxlength="32" placeholder="城市行政区划代码，例如 330100" /><section v-for="(entry, index) in structuredImportForm.entries" :key="index" class="structured-entry"><el-select v-model="entry.source_type" aria-label="资料类型"><el-option value="rule" label="旅行规则" /><el-option value="template" label="城市模板" /></el-select><el-input v-model="entry.title" maxlength="160" placeholder="标题" /><el-input v-model="entry.body_text" type="textarea" :rows="4" maxlength="20000" placeholder="经管理员复核、可公开检索的内容" /><button class="text-action danger" type="button" :disabled="structuredImportForm.entries.length === 1" @click="removeStructuredEntry(index)">移除此条</button></section><button class="secondary-button" type="button" :disabled="structuredImportForm.entries.length >= 50" @click="addStructuredEntry">新增一条</button><p class="import-copy">仅提交已经复核的公共城市规则和模板。系统会对每条资料建立审计记录并直接进入双索引。</p><div class="dialog-actions"><button class="secondary-button" type="button" @click="structuredImportOpen = false">取消</button><button class="primary-button" type="submit">提交导入</button></div></form></el-dialog><el-dialog v-model="retrievalOpen" width="min(760px, calc(100% - 32px))" title="检索验证" destroy-on-close @closed="retrievalResult = null; retrievalError = ''"><form class="source-form" @submit.prevent="submitRetrievalPreview"><el-input v-model="retrievalForm.city_code" maxlength="32" placeholder="城市行政区划代码，例如 330100" /><el-input v-model="retrievalForm.query" type="textarea" :rows="3" maxlength="2000" placeholder="输入要验证的检索问题，例如：西湖周边步行路线安排" /><div class="dialog-actions"><button class="secondary-button" type="button" @click="retrievalOpen = false">关闭</button><button class="primary-button" type="submit" :disabled="retrievalLoading">运行检索</button></div></form><div v-if="retrievalLoading" class="retrieval-state">正在通过生产 RAG 验证索引投影。</div><div v-else-if="retrievalError" class="failure retrieval-state">{{ retrievalError }}</div><section v-else-if="retrievalResult" class="retrieval-result"><p><el-tag effect="plain" :type="tagType(retrievalResult.status)">{{ statusLabel(retrievalResult.status) }}</el-tag><span>{{ retrievalResult.message || `命中 ${retrievalResult.contexts.length} 条公开资料。` }}</span></p><article v-for="context in retrievalResult.contexts" :key="context.citation.chunk_id"><strong>#{{ context.rank }} · {{ context.citation.source_type }} · {{ context.score.toFixed(2) }}</strong><small>{{ context.citation.city_code }} · {{ context.citation.poi_id || context.citation.source_id }} · {{ context.citation.source_updated_at }}</small><p>{{ context.content }}</p></article></section></el-dialog>
    <section class="websearch-workbench" aria-label="网页资料候选审核">
      <div class="websearch-heading"><div><Globe2 :size="18" /><div><strong>网页资料候选审核</strong><span>仅提交受控后台任务；候选资料必须经人工确认后才进入既有知识审核流程。</span></div></div><div class="header-actions"><button class="icon-action" type="button" title="刷新网页搜索任务" :disabled="webSearchLoading" @click="loadWebSearchJobs"><RefreshCw :size="17" :class="{ spinning: webSearchLoading }" /></button><button class="primary-button" type="button" @click="webSearchOpen = true"><Globe2 :size="17" />提交网页搜索</button></div></div>
      <div v-if="webSearchError" class="websearch-error"><CircleAlert :size="18" /><span>{{ webSearchError }}</span><button type="button" @click="loadWebSearchJobs">重新尝试</button></div>
      <div v-else class="websearch-grid"><div class="websearch-jobs"><strong>搜索任务</strong><button v-for="job in webSearchJobs" :key="job.id" class="websearch-job" :class="{ active: webSearchJobId === job.id }" type="button" @click="webSearchJobId = job.id; loadWebSearchCandidates()"><span>{{ job.query }}</span><small>{{ job.city_code }} · {{ job.target_domain === 'official' ? '官方资料' : '社区经验' }} · {{ job.result_count }} 个候选</small><el-tag effect="plain" :type="tagType(job.status)">{{ statusLabel(job.status) }}</el-tag><em v-if="job.error_message">{{ job.error_message }}</em></button><p v-if="!webSearchJobs.length && !webSearchLoading" class="websearch-empty">尚未提交网页搜索任务。</p></div><div class="websearch-candidates"><div class="candidate-heading"><strong>候选资料</strong><span v-if="webSearchJobId">仅候选元数据和摘要；不保存原始网页正文。</span></div><el-table :data="webSearchCandidates" v-loading="webSearchLoading" row-key="id"><el-table-column label="来源与摘要" min-width="310"><template #default="{ row }"><a class="candidate-link" :href="row.source_url" target="_blank" rel="noreferrer">{{ row.title }}</a><small>{{ row.source_host }} · 抓取于 {{ row.fetched_at || row.created_at }}</small><span class="excerpt">{{ row.excerpt }}</span></template></el-table-column><el-table-column label="知识域" width="120"><template #default="{ row }">{{ row.target_domain === 'official' ? '官方资料' : '社区经验' }}</template></el-table-column><el-table-column label="状态" width="130"><template #default="{ row }"><el-tag effect="plain" :type="tagType(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{ row }"><button v-if="row.status === 'needs_human_review'" class="text-action" type="button" @click="openCandidateApproval(row)"><Check :size="16" />审核通过</button><button v-if="row.status === 'needs_human_review'" class="text-action danger" type="button" @click="openCandidateRejection(row)"><X :size="16" />拒绝</button><span v-else class="candidate-decision">{{ row.review_reason || (row.external_web_source_id ? '已提交知识审核' : '已处理') }}</span></template></el-table-column></el-table><p v-if="webSearchJobId && !webSearchLoading && !webSearchCandidates.length" class="websearch-empty">此任务暂无候选资料。</p></div></div>
    </section>
    <section class="community-review-workbench" aria-label="社区知识审核">
      <div class="community-review-heading"><div><Database :size="18" /><div><strong>社区知识审核</strong><span>仅已发布且审核通过的公开社区帖子会进入社区 RAG；私人行程、对话和用户记忆不会进入。</span></div></div><button class="icon-action" type="button" title="刷新社区知识审核队列" @click="loadCommunityKnowledgeReviews"><RefreshCw :size="17" /></button></div>
      <div v-if="communityKnowledgeReviews.length" class="community-review-list"><article v-for="review in communityKnowledgeReviews" :key="review.id" class="community-review-item"><header><div><strong>{{ review.post_title }}</strong><span class="community-review-meta">公开社区帖子 · {{ review.post_city_code || '未填写城市' }} · {{ review.post_status }} · {{ review.created_at }}</span></div><el-tag effect="plain" :type="tagType(review.status)">{{ statusLabel(review.status) }}</el-tag></header><dl class="community-review-provenance"><div><dt>帖子标识</dt><dd>{{ review.post_id }}</dd></div><div><dt>城市</dt><dd>{{ review.post_city_code || '未填写' }}</dd></div><div><dt>帖子状态</dt><dd>{{ review.post_status }}</dd></div><div><dt>提交审核</dt><dd>{{ review.created_at }}</dd></div></dl><div class="community-review-content"><strong>帖子内容</strong><p>{{ review.post_body_text }}</p></div><footer><span>通过后才会提交社区 RAG 索引；处理依据会写入审核记录。</span><div><button class="text-action" type="button" @click="openCommunityKnowledgeReview(review, 'approved')"><Check :size="16" />通过</button><button class="text-action danger" type="button" @click="openCommunityKnowledgeReview(review, 'rejected')"><X :size="16" />拒绝</button></div></footer></article></div>
      <div v-else class="community-review-empty">当前没有等待审核的公开社区帖子。</div>
    </section>
    <section class="external-source-workbench" aria-label="外部网页资料二次审核">
      <div class="external-source-heading"><div><Globe2 :size="18" /><div><strong>外部网页资料二次审核</strong><span>确认来源归属、知识域和正文后，才会将资料提交索引。</span></div></div><button class="icon-action" type="button" title="刷新待二次审核队列" :disabled="webSearchLoading" @click="loadWebSearchJobs"><RefreshCw :size="17" :class="{ spinning: webSearchLoading }" /></button></div>
      <div v-if="webSearchLoading && !externalWebSources.length" class="external-source-empty">正在加载待二次审核资料。</div>
      <div v-else-if="externalWebSources.length" class="external-source-list"><article v-for="source in externalWebSources" :key="source.id" class="external-source-item"><header><div><a class="candidate-link" :href="source.source_url" target="_blank" rel="noreferrer">{{ source.title }}</a><span class="external-source-meta">{{ source.source_host }} · {{ source.city_code }} · {{ source.target_domain === 'official' ? '官方资料' : '社区经验' }}</span></div><el-tag effect="plain" :type="tagType(source.status)">{{ statusLabel(source.status) }}</el-tag></header><dl class="external-source-provenance"><div><dt>来源地址</dt><dd><a :href="source.source_url" target="_blank" rel="noreferrer">{{ source.source_url }}</a></dd></div><div><dt>发布时间</dt><dd>{{ source.published_at || '未提供' }}</dd></div><div><dt>抓取时间</dt><dd>{{ source.fetched_at || source.created_at }}</dd></div><div><dt>候选标识</dt><dd>{{ source.candidate_id }}</dd></div></dl><div class="external-source-content"><strong>审核内容</strong><p>{{ source.body_text }}</p></div><footer><span>通过后将进入索引队列；拒绝原因会写入审核记录。</span><div><button class="text-action" type="button" @click="approveExternalSource(source)"><Check :size="16" />通过并提交索引</button><button class="text-action danger" type="button" @click="openExternalSourceRejection(source)"><X :size="16" />拒绝</button></div></footer></article></div>
      <div v-else class="external-source-empty">当前没有等待二次审核的外部网页资料。</div>
    </section>
    <el-dialog v-model="webSearchOpen" width="min(580px, calc(100% - 32px))" title="提交网页搜索任务" destroy-on-close><form class="source-form" @submit.prevent="submitWebSearch"><el-input v-model="webSearchForm.city_code" maxlength="32" placeholder="城市行政区划代码，例如 330100" /><el-input v-model="webSearchForm.query" type="textarea" :rows="4" maxlength="500" placeholder="输入需要发现的公开资料搜索词" /><el-select v-model="webSearchForm.target_domain" aria-label="目标知识域"><el-option value="official" label="官方资料域" /><el-option value="community" label="社区经验域" /></el-select><p class="import-copy">任务由后端受控处理。前端不直接调用网页搜索服务，也不会传递任何 MCP 配置或密钥。</p><div class="dialog-actions"><button class="secondary-button" type="button" @click="webSearchOpen = false">取消</button><button class="primary-button" type="submit">提交搜索</button></div></form></el-dialog>
    <el-dialog v-model="approveCandidateOpen" width="min(680px, calc(100% - 32px))" title="审核网页候选资料" destroy-on-close><form class="source-form" @submit.prevent="approveCandidate"><el-input v-model="candidateForm.title" maxlength="300" placeholder="审核后的资料标题" /><el-input v-model="candidateForm.body_text" type="textarea" :rows="8" maxlength="20000" show-word-limit placeholder="审核、编辑后可进入既有知识审核的公开内容" /><p class="import-copy">通过后仅创建待审核知识来源，不会直接写入检索索引。</p><div class="dialog-actions"><button class="secondary-button" type="button" @click="approveCandidateOpen = false">取消</button><button class="primary-button" type="submit">确认通过</button></div></form></el-dialog>
    <el-dialog v-model="rejectCandidateOpen" width="min(540px, calc(100% - 32px))" title="拒绝网页候选资料" destroy-on-close><form class="source-form" @submit.prevent="rejectCandidate"><el-input v-model="candidateForm.reason" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="填写拒绝原因" /><div class="dialog-actions"><button class="secondary-button" type="button" @click="rejectCandidateOpen = false">取消</button><button class="primary-button" type="submit">确认拒绝</button></div></form></el-dialog>
    <el-dialog v-model="rejectExternalSourceOpen" width="min(540px, calc(100% - 32px))" title="拒绝外部网页资料" destroy-on-close><form class="source-form" @submit.prevent="rejectExternalSource"><p class="dialog-copy">{{ selectedExternalSource?.title }}</p><el-input v-model="externalSourceReason" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="填写清晰、可复核的拒绝原因" /><div class="dialog-actions"><button class="secondary-button" type="button" @click="rejectExternalSourceOpen = false">取消</button><button class="primary-button" type="submit" :disabled="!externalSourceReason.trim()">确认拒绝</button></div></form></el-dialog>
    <el-dialog v-model="communityReviewOpen" width="min(540px, calc(100% - 32px))" :title="communityReviewDecision === 'approved' ? '通过社区知识审核' : '拒绝社区知识审核'" destroy-on-close><form class="source-form" @submit.prevent="submitCommunityKnowledgeReview"><p class="dialog-copy">{{ selectedCommunityKnowledgeReview?.post_title }}</p><p class="import-copy">{{ communityReviewDecision === 'approved' ? '只有已发布且审核通过的公开社区帖子会进入社区 RAG。' : '拒绝后不会进入社区 RAG。' }}</p><el-input v-model="communityReviewReason" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="填写清晰、可复核的处理依据" /><div class="dialog-actions"><button class="secondary-button" type="button" @click="communityReviewOpen = false">取消</button><button class="primary-button" type="submit" :disabled="!communityReviewReason.trim()">确认{{ communityReviewDecision === 'approved' ? '通过' : '拒绝' }}</button></div></form></el-dialog>
  </main>
</template>

